import {localDate,birthday,occurrence,reminders,totals,validateBackup} from './model.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const empty=()=>({version:1,tasks:[],entries:[],events:[],currency:'HKD',notified:[]});let data;try{const d=JSON.parse(localStorage.getItem('daybook'));data=validateBackup(d)?d:empty()}catch{data=empty()}
let view=['tasks','budget','calendar'].includes(location.hash.slice(1))?location.hash.slice(1):'tasks',taskFilter='all',tagFilter='all',query='',month=localDate().slice(0,7),calendarMonth=month,eventFilter='all',selectedDate=localDate(),editing=null;
const money=n=>new Intl.NumberFormat(undefined,{style:'currency',currency:data.currency||'HKD',maximumFractionDigits:2}).format(n),pretty=d=>new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'}),uid=()=>crypto.randomUUID();
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function save(){try{localStorage.setItem('daybook',JSON.stringify(data))}catch{toast('Storage is full. Export a backup before continuing.');return false}scheduleNative();render();return true}
function scheduleNative(){if(window.DaybookAndroid)window.DaybookAndroid.schedule(JSON.stringify(reminders(data)))}
function heading(title,button,kind){return `<div class="page-heading"><h1>${title}</h1><button class="primary" data-add="${kind}">＋ &nbsp; ${button}</button></div>`}
function blank(icon,title,body,kind,label){return `<div class="empty"><h3>${title}</h3><p>${body}</p>${kind?`<button class="secondary" data-add="${kind}">＋ ${label}</button>`:''}</div>`}
function render(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#nav-count').textContent=data.tasks.filter(t=>!t.done).length;$('#today-label').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'});$('#content').innerHTML=view==='tasks'?taskPage():view==='budget'?budgetPage():calendarPage();bind();}
function taskRow(t,child=false){const children=data.tasks.filter(x=>x.parent===t.id);return `<div class="task-row ${t.done?'done':''} ${child?'child':''}"><button class="check ${t.done?'checked':''}" data-check="${t.id}" aria-label="${t.done?'Reopen':'Complete'} ${esc(t.name)}">${t.done?'✓':''}</button><button class="task-title" data-edit="tasks:${t.id}">${esc(t.name)}${children.length?`<small>${children.filter(c=>c.done).length}/${children.length} subtasks</small>`:''}${t.description?`<small>${esc(t.description)}</small>`:''}</button><div class="task-meta">${t.tags.map(tag=>`<span class="tag ${tag.toLowerCase()==='work'?'work':''}">${esc(tag)}</span>`).join('')}${t.deadline?`<span class="deadline ${!t.done&&t.deadline<localDate()?'overdue':''}">◷ ${pretty(t.deadline)}</span>`:''}${!child?`<button class="row-add" data-sub="${t.id}" title="Add subtask" aria-label="Add subtask">＋</button>`:''}<button class="row-edit" data-edit="tasks:${t.id}" aria-label="Edit task">⋯</button></div></div>${children.map(c=>taskRow(c,true)).join('')}`}
function taskPage(){const active=data.tasks.filter(t=>!t.done),due=active.filter(t=>t.deadline&&t.deadline<=localDate()),done=data.tasks.filter(t=>t.done);let tasks=data.tasks.filter(t=>!t.parent&&(taskFilter==='all'||(taskFilter==='completed'?t.done:!t.done))&&(tagFilter==='all'||t.tags.includes(tagFilter))&&(!query||[t,...data.tasks.filter(c=>c.parent===t.id)].some(x=>x.name.toLowerCase().includes(query.toLowerCase()))));const tags=[...new Set(data.tasks.flatMap(t=>t.tags))];return heading('Tasklist','New task','task')+`<div class="stats"><div><span class="stat-icon green">☑</span><div><small>Open tasks</small><strong>${active.length}</strong></div></div><div><span class="stat-icon amber">◷</span><div><small>Due today & overdue</small><strong>${due.length}</strong></div></div><div><span class="stat-icon lavender">✓</span><div><small>Completed</small><strong>${done.length}</strong></div></div></div><div class="panel"><div class="panel-tools"><div class="tabs">${['all','active','completed'].map(f=>`<button data-task-filter="${f}" class="${taskFilter===f?'selected':''}">${f==='all'?'All tasks':f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div><div class="filters"><input id="task-search" type="search" placeholder="Search tasks…" value="${esc(query)}" aria-label="Search tasks"><select id="tag-filter" aria-label="Filter tags"><option value="all">All tags</option>${tags.map(t=>`<option ${t===tagFilter?'selected':''}>${esc(t)}</option>`).join('')}</select></div></div><div class="list-header"><span>TASK</span><span>TAGS & DEADLINE</span></div>${tasks.length?tasks.map(t=>taskRow(t)).join(''):blank('✓',data.tasks.length?'No matching tasks':'No tasks','Add a task to get started.','task','Add your first task')}</div>`}
function budgetPage(){const list=data.entries.filter(e=>e.date.startsWith(month)).sort((a,b)=>b.date.localeCompare(a.date));const t=totals(data.entries,month);return heading('Budget','New entry','entry')+`<div class="month-toolbar"><h3>${new Date(month+'-01T12:00:00').toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h3><input type="month" id="budget-month" value="${month}" aria-label="Budget month"></div><div class="stats"><div><span class="stat-icon green">↙</span><div><small>Revenue</small><strong class="money">${money(t.revenue)}</strong></div></div><div><span class="stat-icon amber">↗</span><div><small>Expenses</small><strong class="money">${money(t.expenses)}</strong></div></div><div><span class="stat-icon lavender">≈</span><div><small>Balance</small><strong class="money">${money(t.revenue-t.expenses)}</strong></div></div></div><div class="budget-layout"><div class="panel"><div class="panel-title"><h3>Transactions</h3><span>${list.length} entries</span></div>${list.length?list.map(e=>`<button class="transaction" data-edit="entries:${e.id}"><span class="expense-icon ${e.type==='revenue'?'green':'amber'}">${e.type==='revenue'?'↙':'↗'}</span><span class="transaction-name">${esc(e.name)}<small>${esc(e.description||e.type)} · ${pretty(e.date)}</small></span><span class="transaction-amount ${e.type==='revenue'?'income':''}">${e.type==='revenue'?'+':'−'}${money(e.amount)}<small>${esc(e.type)}</small></span></button>`).join(''):blank('↗','No entries this month','Add an expense or revenue entry.','entry','Add an entry')}</div><div class="panel breakdown"><h3>Spending by category</h3>${['game expenses','subscriptions','food'].map(type=>{const n=list.filter(e=>e.type===type).reduce((s,e)=>s+e.amount,0);return `<div class="category"><div><span>${type[0].toUpperCase()+type.slice(1)}</span><strong>${money(n)}</strong></div><div class="bar"><span style="width:${t.expenses?n/t.expenses*100:0}%"></span></div></div>`}).join('')}</div></div>`}
function itemsOn(date){const year=Number(date.slice(0,4));return [...data.tasks.filter(t=>!t.done&&t.deadline===date).map(t=>({...t,kind:'task'})),...data.events.filter(e=>occurrence(e,year)===date).map(e=>({...e,kind:birthday(e.name)?'birthday':'event'}))].filter(e=>eventFilter==='all'||(eventFilter==='birthdays'?e.kind==='birthday':e.kind==='task'))}
function calendarPage(){const first=new Date(calendarMonth+'-01T12:00:00'),year=first.getFullYear(),m=first.getMonth(),days=new Date(year,m+1,0).getDate(),offset=(first.getDay()+6)%7;let cells='';for(let i=0;i<42;i++){const d=localDate(new Date(year,m,1+i-offset)),outside=d.slice(0,7)!==calendarMonth,items=itemsOn(d);cells+=`<button data-date="${d}" class="day ${outside?'outside':''} ${d===localDate()?'today':''} ${d===selectedDate?'picked':''}" aria-label="${d}, ${items.length} events"><span class="day-number">${Number(d.slice(-2))}</span><div>${items.slice(0,3).map(e=>`<span class="calendar-event ${e.kind}">${esc(e.name)}</span>`).join('')}${items.length>3?`<small>+${items.length-3} more</small>`:''}</div></button>`}const agenda=itemsOn(selectedDate);const birthdays=data.events.filter(e=>birthday(e.name)).sort((a,b)=>a.date.slice(5).localeCompare(b.date.slice(5)));return heading('Calendar','New event','event')+`<div class="calendar-toolbar"><div class="month-nav"><button data-month="-1" aria-label="Previous month">‹</button><h3>${first.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h3><button data-month="1" aria-label="Next month">›</button><button id="calendar-today" class="secondary">Today</button></div><div class="tabs">${[['all','Everything'],['tasks','Tasks'],['birthdays','Birthdays']].map(([f,label])=>`<button data-event-filter="${f}" class="${eventFilter===f?'selected':''}">${label}</button>`).join('')}</div></div><div class="calendar-layout"><div class="panel calendar-panel"><div class="weekdays">${['MON','TUE','WED','THU','FRI','SAT','SUN'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${cells}</div><div class="legend"><span>● Task deadline</span><span>● Event</span><span>● Birthday</span></div></div><div><div class="panel agenda"><div class="panel-title"><h3>${pretty(selectedDate)}</h3><button data-add="event" class="row-add" aria-label="Add event on selected date">＋</button></div>${agenda.length?agenda.map(e=>`<button class="agenda-item" data-edit="${e.kind==='task'?'tasks':'events'}:${e.id}"><span class="agenda-dot ${e.kind}"></span><div>${esc(e.name)}<small>${e.kind==='task'?'Task deadline':e.time||'All day'}${e.kind==='birthday'?' · Annual birthday':''}</small></div></button>`).join(''):'<p class="muted">No events on this date.</p>'}</div><div class="birthday-card"><h3>Birthday list</h3>${birthdays.length?birthdays.map(e=>`<button data-edit="events:${e.id}"><span>${esc(e.name)}</span><small>${pretty(e.date)}</small></button>`).join(''):'<p>No birthdays. Add an event with “birthday” or “bday” in its name.</p>'}<small>Annual reminders at midnight.</small></div></div></div>`}
function field(label,input){return `<label>${label}${input}</label>`}
function openEditor(kind,id=null,parent=null){const key={task:'tasks',entry:'entries',event:'events'}[kind],item=data[key].find(x=>x.id===id)||{};editing={kind,key,id,parent:parent||item.parent||null};$('#dialog-title').textContent=(id?'Edit ':parent?'New sub':'New ')+(kind==='entry'?'budget entry':kind);$('#delete-item').hidden=!id;let html=field('Name',`<input name="name" required maxlength="200" autofocus placeholder="${kind==='task'?'Task name':kind==='entry'?'Entry name':'Event name'}" value="${esc(item.name)}">`);if(kind!=='event')html+=field('Description <span class="optional">optional</span>',`<textarea name="description" maxlength="1000" placeholder="Description">${esc(item.description)}</textarea>`);if(kind==='task')html+=`<div class="form-grid">${field('Deadline <span class="optional">optional</span>',`<input type="date" name="deadline" value="${item.deadline||''}">`)}${field('Tags',`<input name="tags" placeholder="work, personal" value="${esc(item.tags?.join(', ')||'')}">`)}</div><p class="form-hint">◷ Reminders arrive one day before the deadline.</p>`;if(kind==='entry')html+=`<div class="form-grid">${field('Amount',`<input type="number" name="amount" min="0.01" max="999999999" step="0.01" required placeholder="0.00" value="${item.amount||''}">`)}${field('Type',`<select name="type">${['revenue','game expenses','subscriptions','food'].map(t=>`<option value="${t}" ${item.type===t?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select>`)}</div>${field('Date <span class="optional">defaults to today</span>',`<input type="date" name="date" value="${item.date||''}">`)}`;if(kind==='event')html+=`<div class="form-grid">${field('Date',`<input name="date" type="date" required value="${item.date||selectedDate}">`)}${field('Time <span class="optional">optional</span>',`<input type="time" name="time" value="${item.time||''}">`)}</div><label class="checkbox-label"><input name="remind" type="checkbox" ${item.remind?'checked':''}> Remind me at the start of this event</label><p class="form-hint">No time means all day. “Birthday” and “bday” events repeat yearly with a midnight reminder.</p>`;$('#editor-fields').innerHTML=html;$('#editor').showModal()}
function bind(){document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openEditor(b.dataset.add));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const[k,id]=b.dataset.edit.split(':');openEditor({tasks:'task',entries:'entry',events:'event'}[k],id)});document.querySelectorAll('[data-sub]').forEach(b=>b.onclick=()=>openEditor('task',null,b.dataset.sub));document.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>{const t=data.tasks.find(t=>t.id===b.dataset.check);t.done=!t.done;if(t.done)data.tasks.filter(x=>x.parent===t.id).forEach(x=>x.done=true);if(!t.done&&t.parent)data.tasks.find(x=>x.id===t.parent).done=false;save()});document.querySelectorAll('[data-task-filter]').forEach(b=>b.onclick=()=>{taskFilter=b.dataset.taskFilter;render()});if($('#task-search'))$('#task-search').oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('#task-search').focus();$('#task-search').setSelectionRange(pos,pos)};if($('#tag-filter'))$('#tag-filter').onchange=e=>{tagFilter=e.target.value;render()};if($('#budget-month'))$('#budget-month').onchange=e=>{if(e.target.value){month=e.target.value;render()}};document.querySelectorAll('[data-event-filter]').forEach(b=>b.onclick=()=>{eventFilter=b.dataset.eventFilter;render()});document.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{const d=new Date(calendarMonth+'-01T12:00:00');d.setMonth(d.getMonth()+Number(b.dataset.month));calendarMonth=localDate(d).slice(0,7);render()});document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{const d=b.dataset.date;selectedDate=d;render();openEditor('event')});if($('#calendar-today'))$('#calendar-today').onclick=()=>{calendarMonth=localDate().slice(0,7);selectedDate=localDate();render()}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;location.hash=view;render()});window.onhashchange=()=>{if(['tasks','budget','calendar'].includes(location.hash.slice(1))){view=location.hash.slice(1);render()}};
$('#editor-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),{kind,key,id,parent}=editing,item=data[key].find(x=>x.id===id),name=f.get('name').trim();if(!name)return;let values={id:id||uid(),name};if(kind==='task')Object.assign(values,{description:f.get('description').trim(),deadline:f.get('deadline'),tags:[...new Set(f.get('tags').split(',').map(s=>s.trim()).filter(Boolean))],parent,done:item?.done||false});if(kind==='entry')Object.assign(values,{description:f.get('description').trim(),amount:Number(f.get('amount')),date:f.get('date')||localDate(),type:f.get('type')});if(kind==='event')Object.assign(values,{date:f.get('date'),time:f.get('time'),remind:f.has('remind')});if(item)Object.assign(item,values);else data[key].push(values);if(kind==='task'&&parent&&!values.done)data.tasks.find(t=>t.id===parent).done=false;if(save()){$('#editor').close();toast(id?'Changes saved':kind==='task'?'Task added':kind==='entry'?'Entry recorded':'Event added')}};
$('#delete-item').onclick=()=>{const{key,id}=editing;const children=key==='tasks'?data.tasks.filter(t=>t.parent===id).length:0;if(!confirm(children?`Delete this task and its ${children} subtasks?`:'Delete this item?'))return;data[key]=data[key].filter(x=>x.id!==id&&(key!=='tasks'||x.parent!==id));save();$('#editor').close();toast('Item deleted')};['close-dialog','cancel-dialog'].forEach(id=>$('#'+id).onclick=()=>$('#editor').close());$('#settings-open').onclick=()=>{$('#currency').value=data.currency;$('#settings').showModal()};$('#settings-top').onclick=$('#settings-open').onclick;$('#close-settings').onclick=()=>$('#settings').close();$('#currency').onchange=e=>{data.currency=e.target.value;save()};$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});if(window.DaybookAndroid){window.DaybookAndroid.exportBackup(JSON.stringify(data));return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='personal-'+localDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#import').onchange=async e=>{try{const imported=JSON.parse(await e.target.files[0].text());if(!validateBackup(imported))throw Error('Invalid');if(!confirm('Replace this device’s data with the backup? Export your current data first if you need it.'))return;data={...imported,currency:['HKD','USD','EUR','GBP','JPY'].includes(imported.currency)?imported.currency:'HKD',notified:[]};save();$('#currency').value=data.currency;toast('Backup imported')}catch{toast('This file is not a valid Personal backup.')}finally{e.target.value=''}};
async function enableNotifications(){if(window.DaybookAndroid){window.DaybookAndroid.requestNotifications();scheduleNative();return}if(!('Notification'in window)){toast('Notifications are unavailable in this browser.');return}const permission=await Notification.requestPermission();toast(permission==='granted'?'Reminders enabled while Personal is open.':'Allow notifications in your browser settings.');checkReminders()}
$('#notifications').onclick=enableNotifications;$('#settings-notifications').onclick=enableNotifications;
async function checkReminders(){if(window.DaybookAndroid||!('Notification'in window)||Notification.permission!=='granted')return;const now=Date.now();for(const r of reminders(data,new Date(now-86400000))){if(r.at>now||data.notified?.includes(r.id))continue;try{const reg=await navigator.serviceWorker?.getRegistration();if(reg)await reg.showNotification('Personal',{body:r.title,tag:r.id,icon:'icon.svg'});else new Notification('Personal',{body:r.title});data.notified=[...(data.notified||[]),r.id];localStorage.setItem('daybook',JSON.stringify(data))}catch{}}}
if('serviceWorker'in navigator&&!window.DaybookAndroid)navigator.serviceWorker.register('./sw.js').catch(()=>{});render();scheduleNative();checkReminders();setInterval(checkReminders,30000);window.addEventListener('focus',checkReminders);

